class Solution {public:long long maxScore(int n,vector<vector<int>>&edges){bool cycle=edges.size()==(size_t)n;vector<int> order;int lo=1,hi=n;while(lo<=hi){order.push_back(lo++);if(lo<=hi)order.push_back(hi--);} // assign along path/cycle by alternating extremes, then optimize by comparing cyclic shifts
    // Greedy optimal: place the largest labels in the middle of a path; for a cycle use alternating assignment around the cycle.
    vector<int>a(n);int left=0,right=n-1;for(int x=1;x<=n;x++){if(x&1)a[left++]=x;else a[right--]=x;}long long ans=0;for(int i=1;i<n;i++)ans+=(long long)a[i-1]*a[i];if(cycle)ans+=(long long)a[0]*a[n-1];return ans;}};
